INSERT INTO `ex_security` (`no`, `question`, `A`, `B`, `C`, `D`, `answer`, `A_time`, `B_time`, `C_time`, `D_time`) VALUES
(1, '以下何者不是電腦病毒的特性?', '寄生', '繁衍', '發病', '死亡', 'D', 0, 0, 1, 2),
(2, '網路防火牆(firewall)指的是？', '可以增加網路頻寬(bandwidth)的設備', '用來保護電腦網路主機的防火水泥牆', '可以過濾非法連線，避免駭客(hacker)存取的設備', '可以防止電腦遭受病毒(virus)攻擊的設備', 'C', 1, 0, 2, 0),
(3, '下列何種密碼(password)較為安全？', '4 個文數字', '全部是英文', '全由數字組成', '包含特殊字元，並避免使用與個人有關資料', 'D', 2, 0, 0, 2),
